INSERT INTO "app_link" VALUES('lm-app-battle-abbey-approx','lm-s-eh-battle','2026-11-14','high','attested-documentary',NULL,NULL,NULL,NULL,'lm-p-battle-abbey','data/national/places.json','battle-abbey','/131/phases','uncertainty','[{"from": 1071, "to": 1538, "label": "Benedictine abbey on the battlefield of 1066", "size": 2}, {"from": 1539, "to": null, "label": "Country house in the abbey buildings", "size": 1, "kind": "other"}]','The institutional source presents the foundation as approximate. Keep a circa flag rather than treating the displayed year as exact.',2);
INSERT INTO "app_link" VALUES('lm-app-margam-approx','lm-s-wal-coflein-margam','2026-11-14','high','attested-documentary',NULL,NULL,NULL,NULL,'lm-p-margam','data/national/places-wales.json','margam','/56/phases','uncertainty','[{"from": 1147, "to": 1536, "label": "Cistercian abbey", "size": 2}, {"from": 1536, "to": null, "label": "Nave kept as parish church", "size": 1}]','The institutional source presents the foundation as approximate. Keep a circa flag rather than treating the displayed year as exact.',2);
INSERT INTO "app_link" VALUES('lm-app-peterborough-dissolution','lm-s-nat-vch-peterborough-abbey','2026-11-14','high','attested-documentary',NULL,NULL,NULL,NULL,'lm-p-peterborough','data/national/places.json','peterborough','/104/phases','refinement','[{"from": 655, "to": 869, "label": "Medeshamstede, Mercian monastery", "size": 2}, {"from": 870, "to": 965, "label": "Destroyed by the Danes", "size": 0}, {"from": 966, "to": 1539, "label": "Refounded Benedictine abbey", "size": 3}, {"from": 1540, "to": null, "label": "Abbey church kept as a cathedral (see founded 1541)", "size": 2, "kind": "cathedral"}]','Suppression date independently verified as {''year'': 1539, ''calendar'': ''Julian'', ''precision'': ''day'', ''circa'': False, ''month'': 11, ''day'': 29}. Closure and destruction are different phases; do not delay or force demolition to a following year.',3);
