INSERT INTO "dispute" VALUES('lm-d-halidon-date','lm-s-bt-halidon','2026-11-14','medium','attested-documentary','Source disagreement is not an assertion of equal historical probability.',NULL,NULL,NULL,'Battle of Halidon Hill - 1333 dating','Source table gives 13 July; same source narrative gives 19 July. Retained at month precision pending resolution.','chronological_uncertainty');
