INSERT INTO "todo" VALUES('lm-todo-date-edgcote','lm-s-bt-edgcote','2026-11-14','medium','attested-documentary',NULL,NULL,NULL,NULL,'Battle of Edgcote - 1469 alternate chronology','Fetch an independent critical source for the competing date; do not silently normalize the date.',2,'done','Fetched Historic England NHLE entry supplies competing 26 July claim; Trust currently gives 24 July.','https://www.battlefieldstrust.com/resource-centre/warsoftheroses/battleview.asp?BattleFieldId=13','lm-e-edgcote');
