INSERT INTO "todo" VALUES('pr-todo-coordinates','pr-s-app','2026-11-14','high','attested-documentary',NULL,NULL,NULL,NULL,'Independent English site coordinates','Replace provisional app points with HE/Pleiades/HER gazetteer or registered-boundary coordinates.',1,'open','Most English points are carried only to allow entity matching; all explicitly have 1 km uncertainty.','https://historicengland.org.uk/listing/the-list/',NULL);
INSERT INTO "todo" VALUES('pr-todo-hillforts','pr-s-app','2026-11-14','high','attested-documentary',NULL,NULL,NULL,NULL,'Hillfort and settlement breadth','Verify Danebury, Hambledon Hill, Cissbury, Cadbury Castle, Glastonbury Lake Village, Hengistbury Head and regional Welsh hillforts.',1,'open','Not covered by this bounded source pass; do not reuse app chronology as evidence.','https://hillforts.arch.ox.ac.uk/',NULL);
INSERT INTO "todo" VALUES('pr-todo-causeways','pr-s-app','2026-11-14','high','attested-documentary',NULL,NULL,NULL,NULL,'Wetland monuments','Follow excavation reports for Flag Fen and Sweet Track, including dendrochronological sequences and deposition duration.',2,'open','App Flag Fen claim is based on Wikipedia; no institutional original checked here.','https://historicengland.org.uk/research/results/reports/',NULL);
INSERT INTO "todo" VALUES('pr-todo-radiocarbon','pr-s-app','2026-11-14','high','attested-documentary',NULL,NULL,NULL,NULL,'Modern prehistoric dating models','Replace visitor-page rounding with calibrated model intervals, probability levels and radiocarbon likelihoods for Stonehenge, West Kennet and Durrington.',1,'open','Current institutional summaries are useful but cannot resolve each construction event.','https://www.cambridge.org/core/journals/antiquity',NULL);
INSERT INTO "todo" VALUES('pr-todo-bryn-sequence','pr-s-app','2026-11-14','high','attested-documentary',NULL,NULL,NULL,NULL,'Bryn Celli Ddu sequence','Check modern excavation reinterpretations of the alleged preceding henge and tomb chronology.',2,'open','Cadw describes a henge predecessor; app flags scholarly doubt; contrary publication not fetched.','https://coflein.gov.uk/',NULL);
INSERT INTO "todo" VALUES('pr-todo-caerleon-end','pr-s-app','2026-11-14','high','attested-documentary',NULL,NULL,NULL,NULL,'Caerleon late occupation','Check Knight 2003 and later excavations on reduced military versus civilian occupation after 300.',1,'open','Coflein headline simplifies departure; continuing fourth-century activity needs separate evidence.','https://coflein.gov.uk/en/sites/275985',NULL);
INSERT INTO "todo" VALUES('pr-todo-segontium-end','pr-s-app','2026-11-14','high','attested-documentary',NULL,NULL,NULL,NULL,'Segontium 338/394 conflict','Consult Casey, Davies and Evans, Excavations at Segontium (1993), coin sequence and occupation argument.',1,'open','Two fetched summaries conflict; no winner selected.','https://pleiades.stoa.org/places/79678',NULL);
INSERT INTO "todo" VALUES('pr-todo-provinces','pr-s-app','2026-11-14','high','attested-documentary',NULL,NULL,NULL,NULL,'Provincial reforms','Verify dated inscriptions and late lists for division around 197–213 and Diocletianic provinces; resolve capital/boundary alternatives.',1,'open','Simple visitor accounts overstate territorial precision; polygon reconstruction deliberately omitted.','https://romaninscriptionsofbritain.org/',NULL);
INSERT INTO "todo" VALUES('pr-todo-caesar','pr-s-app','2026-11-14','high','attested-documentary',NULL,NULL,NULL,NULL,'Caesar’s expeditions','Read Bellum Gallicum 4.20–38 and 5.8–23; encode landings, Kent encounters, Thames crossing and Cassivellaunus without speculative sites.',1,'open','Only expedition-year skeleton recorded so far.','https://classics.mit.edu/Caesar/gallic.html',NULL);
INSERT INTO "todo" VALUES('pr-todo-conquest-river','pr-s-app','2026-11-14','high','attested-documentary',NULL,NULL,NULL,NULL,'River battle of 43','Compare competing Medway/other identifications against Dio and excavation evidence.',1,'open','Dio does not name the first river; no modern battlefield point asserted.','https://www.english-heritage.org.uk/learn/story-of-england/romans/roman-invasion/',NULL);
