INSERT INTO "todo" VALUES('pr-todo-roads','pr-s-app','2026-11-14','high','attested-documentary',NULL,NULL,NULL,NULL,'Road linework and stations','Resolve each Antonine Itinerary station and excavated/LiDAR road segment with provenance and uncertainty.',1,'open','Four routes here are schematic node lists, not verified polylines; many app routes not audited.','https://itiner-e.org/',NULL);
INSERT INTO "todo" VALUES('pr-todo-legions','pr-s-app','2026-11-14','high','attested-documentary',NULL,NULL,NULL,NULL,'Garrison tenures','Read RIB inscriptions and Vindolanda tablets to refine dated garrison evidence, command structures and troop establishments.',2,'open','Institutional named garrisons are verified; primary inscriptions generally cited second-hand.','https://romaninscriptionsofbritain.org/',NULL);
